import { prisma } from '@/lib/prisma'
import { requireAuth } from '@/lib/auth'
import { redirect } from 'next/navigation'
import { Plane, User, CheckCircle, Clock } from 'lucide-react'
import { formatDistanceToNow } from 'date-fns'
import { resolveActiveAirlineId } from '@/lib/active-airline'

export default async function AirlineFeedPage() {
  const session = await requireAuth()
  const selectedAirlineId = await resolveActiveAirlineId(session.user)
  if (!selectedAirlineId) redirect('/dashboard')

  const airline = await prisma.airline.findUnique({
    where: { id: selectedAirlineId },
  })
  if (!airline) redirect('/dashboard')

  const recentPireps = await prisma.pirep.findMany({
    where: { route_ref: { airlineId: airline.id } },
    orderBy: { submittedAt: 'desc' },
    take: 30,
    include: {
      pilot: { select: { callsign: true, rank: { select: { name: true, code: true } } } },
      route_ref: { select: { flightNumber: true, depIcao: true, arrIcao: true } },
    },
  })

  return (
    <div className="space-y-5 max-w-2xl">
      <h1 className="section-title">Activity Feed</h1>

      {recentPireps.length === 0 ? (
        <div className="card text-center py-12 text-slate-500">No activity yet. Flights will appear here once submitted.</div>
      ) : (
        <div className="space-y-2">
          {recentPireps.map((p) => (
            <div key={p.id} className="card flex items-center gap-4">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${p.status === 'ACCEPTED' ? 'bg-emerald-500/10' : p.status === 'PENDING' ? 'bg-amber-500/10' : 'bg-red-500/10'}`}>
                {p.status === 'ACCEPTED' ? <CheckCircle className="w-4 h-4 text-emerald-400" /> : p.status === 'PENDING' ? <Clock className="w-4 h-4 text-amber-400" /> : <Plane className="w-4 h-4 text-red-400" />}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-medium text-slate-900 dark:text-white">
                  <span className="font-mono">{p.route_ref?.flightNumber}</span>
                  {p.route_ref && <span className="text-slate-500 font-normal"> · {p.route_ref.depIcao} → {p.route_ref.arrIcao}</span>}
                </div>
                <div className="text-xs text-slate-500 flex items-center gap-1">
                  <User className="w-3 h-3" />
                  {p.pilot?.callsign} {p.pilot?.rank && `· ${p.pilot.rank.code}`}
                </div>
              </div>
              <div className="text-right">
                <span className={`badge-status text-xs ${p.status === 'ACCEPTED' ? 'text-emerald-400 bg-emerald-500/10' : p.status === 'PENDING' ? 'text-amber-400 bg-amber-500/10' : 'text-red-400 bg-red-500/10'}`}>
                  {p.status}
                </span>
                <div className="text-xs text-slate-500 mt-1">{formatDistanceToNow(new Date(p.submittedAt), { addSuffix: true })}</div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
